import Foundation

/// Everything the mobile app needs from GitHub, implemented purely over the REST API.
enum GitHubApiService {
    static let apiBase = "https://api.github.com"
    static let defaultHugoPagesWorkflow = """
    # Generated by Hugoer Mobile
    name: Deploy Hugo site to Pages

    on:
      push:
        branches: ["main", "master"]
      workflow_dispatch:

    permissions:
      contents: read
      pages: write
      id-token: write

    concurrency:
      group: "pages"
      cancel-in-progress: false

    defaults:
      run:
        shell: bash

    jobs:
      build:
        runs-on: ubuntu-latest
        env:
          HUGO_VERSION: 0.164.0
        steps:
          - name: Checkout
            uses: actions/checkout@v4
            with:
              submodules: recursive
              fetch-depth: 0

          - name: Setup Hugo
            uses: peaceiris/actions-hugo@v3
            with:
              hugo-version: ${{ env.HUGO_VERSION }}
              extended: true

          - name: Setup Pages
            id: pages
            uses: actions/configure-pages@v5

          - name: Build with Hugo
            env:
              HUGO_ENVIRONMENT: production
            run: |
              hugo --gc --minify --baseURL "${{ steps.pages.outputs.base_url }}/"

          - name: Upload artifact
            uses: actions/upload-pages-artifact@v3
            with:
              path: ./public

      deploy:
        environment:
          name: github-pages
          url: ${{ steps.deployment.outputs.page_url }}
        runs-on: ubuntu-latest
        needs: build
        steps:
          - name: Deploy to GitHub Pages
            id: deployment
            uses: actions/deploy-pages@v4
    """

    // MARK: - Users / repos

    static func getAuthenticatedUserLogin(token: String) async throws -> String? {
        let (data, response) = try await send(method: "GET", path: "user", token: token)
        guard isSuccess(response) else { return nil }
        let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        return json?["login"] as? String
    }

    static func getRepoInfo(owner: String, repo: String, token: String) async throws -> GitHubRepoInfo? {
        let (data, response) = try await send(method: "GET", path: "repos/\(owner)/\(repo)", token: token)
        guard isSuccess(response) else { return nil }
        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return nil }

        let permissions = json["permissions"] as? [String: Any]
        return GitHubRepoInfo(
            owner: owner,
            name: repo,
            defaultBranch: json["default_branch"] as? String ?? "main",
            isPrivate: json["private"] as? Bool ?? false,
            htmlUrl: json["html_url"] as? String ?? "https://github.com/\(owner)/\(repo)",
            description: json["description"] as? String,
            permissions: RepoPermissions(
                pull: permissions?["pull"] as? Bool ?? false,
                push: permissions?["push"] as? Bool ?? false,
                admin: permissions?["admin"] as? Bool ?? false
            )
        )
    }

    // MARK: - Contents API

    static func tryGetFile(owner: String, repo: String, path: String, branch: String, token: String) async throws -> GitHubFileContent? {
        let encodedPath = encodePath(path)
        let query = "?ref=\(encodeQueryValue(branch))"
        let (data, response) = try await send(method: "GET", path: "repos/\(owner)/\(repo)/contents/\(encodedPath)\(query)", token: token)

        if response.statusCode == 404 { return nil }
        try ensureSuccess(response, data: data)

        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              json["type"] as? String == "file" else { return nil }

        guard let sha = json["sha"] as? String else { return nil }
        let base64 = (json["content"] as? String) ?? ""
        let text = decodeBase64(base64)
        return GitHubFileContent(path: path, sha: sha, textContent: text)
    }

    static func listDirectory(owner: String, repo: String, path: String, branch: String, token: String) async throws -> [ContentItem] {
        let encodedPath = encodePath(path)
        let query = "?ref=\(encodeQueryValue(branch))"
        let (data, response) = try await send(method: "GET", path: "repos/\(owner)/\(repo)/contents/\(encodedPath)\(query)", token: token)

        if response.statusCode == 404 { return [] }
        try ensureSuccess(response, data: data)

        guard let array = try? JSONSerialization.jsonObject(with: data) as? [[String: Any]] else { return [] }

        var items: [ContentItem] = []
        for obj in array {
            let type = obj["type"] as? String
            items.append(ContentItem(
                name: obj["name"] as? String ?? "",
                path: obj["path"] as? String ?? "",
                isDirectory: type == "dir",
                sha: obj["sha"] as? String,
                size: (obj["size"] as? NSNumber)?.int64Value ?? 0
            ))
        }

        return items.sorted { a, b in
            if a.isDirectory != b.isDirectory { return a.isDirectory && !b.isDirectory }
            return a.name.localizedCaseInsensitiveCompare(b.name) == .orderedAscending
        }
    }

    static func putFile(
        owner: String, repo: String, path: String, textContent: String, commitMessage: String,
        sha: String?, branch: String, token: String
    ) async throws -> GitHubFileContent {
        var body: [String: Any] = [
            "message": commitMessage,
            "content": encodeBase64(textContent),
            "branch": branch,
        ]
        if let sha, !sha.isEmpty {
            body["sha"] = sha
        }

        let (data, response) = try await send(method: "PUT", path: "repos/\(owner)/\(repo)/contents/\(encodePath(path))", token: token, jsonBody: body)
        try ensureSuccess(response, data: data)

        let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        let content = json?["content"] as? [String: Any]
        let newSha = (content?["sha"] as? String) ?? sha ?? ""
        return GitHubFileContent(path: path, sha: newSha, textContent: textContent)
    }

    static func deleteFile(
        owner: String, repo: String, path: String, sha: String, commitMessage: String,
        branch: String, token: String
    ) async throws {
        let body: [String: Any] = [
            "message": commitMessage,
            "sha": sha,
            "branch": branch,
        ]
        let (data, response) = try await send(method: "DELETE", path: "repos/\(owner)/\(repo)/contents/\(encodePath(path))", token: token, jsonBody: body)
        try ensureSuccess(response, data: data)
    }

    // MARK: - Actions

    static func listWorkflows(owner: String, repo: String, token: String) async throws -> [GitHubWorkflowInfo] {
        let (data, response) = try await send(method: "GET", path: "repos/\(owner)/\(repo)/actions/workflows", token: token)
        guard isSuccess(response) else { return [] }
        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let array = json["workflows"] as? [[String: Any]] else { return [] }

        return array.map { obj in
            GitHubWorkflowInfo(
                id: (obj["id"] as? NSNumber)?.int64Value ?? 0,
                name: obj["name"] as? String ?? "",
                path: obj["path"] as? String ?? ""
            )
        }
    }

    static func listWorkflowRuns(owner: String, repo: String, token: String, take: Int = 10) async throws -> [WorkflowRunInfo] {
        let (data, response) = try await send(method: "GET", path: "repos/\(owner)/\(repo)/actions/runs?per_page=\(take)", token: token)
        guard isSuccess(response) else { return [] }
        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let array = json["workflow_runs"] as? [[String: Any]] else { return [] }

        return array.map(mapRun)
    }

    static func dispatchWorkflow(owner: String, repo: String, workflowId: Int64, branch: String, token: String) async throws {
        let body: [String: Any] = ["ref": branch]
        let (data, response) = try await send(method: "POST", path: "repos/\(owner)/\(repo)/actions/workflows/\(workflowId)/dispatches", token: token, jsonBody: body)
        try ensureSuccess(response, data: data)
    }

    // MARK: - Pages

    static func getPagesStatus(owner: String, repo: String, token: String) async throws -> GitHubPagesStatus {
        let (data, response) = try await send(method: "GET", path: "repos/\(owner)/\(repo)/pages", token: token)

        if response.statusCode == 404 {
            return GitHubPagesStatus(enabled: false, message: "GitHub Pages 尚未啟用。")
        }

        guard isSuccess(response) else {
            return GitHubPagesStatus(enabled: false, message: readError(data: data, response: response))
        }

        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return GitHubPagesStatus(enabled: false, message: "無法解析 Pages 回應。")
        }

        let status = json["status"] as? String
        let source = json["source"] as? [String: Any]

        let message: String
        switch status {
        case "built": message = "網站已成功建置並上線。"
        case "building": message = "正在建置中…"
        case "errored": message = "建置發生錯誤，請至 Actions 檢查日誌。"
        case .none: message = "GitHub Pages 已啟用。"
        default: message = "狀態：\(status ?? "")"
        }

        return GitHubPagesStatus(
            enabled: true,
            status: status,
            htmlUrl: json["html_url"] as? String,
            sourceBranch: source?["branch"] as? String,
            sourcePath: source?["path"] as? String,
            buildType: json["build_type"] as? String,
            message: message
        )
    }

    static func enablePagesFromActions(owner: String, repo: String, token: String) async throws -> (success: Bool, message: String) {
        let (_, existing) = try await send(method: "GET", path: "repos/\(owner)/\(repo)/pages", token: token)
        let pagesExist = isSuccess(existing)

        let method = pagesExist ? "PUT" : "POST"
        let body: [String: Any] = ["build_type": "workflow"]
        let (data, response) = try await send(method: method, path: "repos/\(owner)/\(repo)/pages", token: token, jsonBody: body)

        if isSuccess(response) {
            return (true, pagesExist ? "已將 GitHub Pages 建置來源更新為 GitHub Actions。" : "已啟用 GitHub Pages（GitHub Actions）。")
        }

        return (false, readError(data: data, response: response))
    }

    static func ensureDeployWorkflow(owner: String, repo: String, branch: String, token: String) async throws {
        let path = ".github/workflows/hugo.yml"
        let existing = try await tryGetFile(owner: owner, repo: repo, path: path, branch: branch, token: token)
        if existing != nil { return }

        _ = try await putFile(
            owner: owner, repo: repo, path: path, textContent: defaultHugoPagesWorkflow,
            commitMessage: "Add Hugo Pages workflow via Hugoer Mobile", sha: nil, branch: branch, token: token
        )
    }

    // MARK: - Internals

    private static func mapRun(_ obj: [String: Any]) -> WorkflowRunInfo {
        let status: WorkflowRunStatus
        switch obj["status"] as? String {
        case "queued": status = .queued
        case "in_progress": status = .inProgress
        case "completed": status = .completed
        default: status = .unknown
        }

        let conclusion: WorkflowRunConclusion
        switch obj["conclusion"] as? String {
        case "success": conclusion = .success
        case "failure": conclusion = .failure
        case "cancelled": conclusion = .cancelled
        case "skipped": conclusion = .skipped
        case .none: conclusion = .none
        default: conclusion = .other
        }

        var createdAt = Date()
        if let createdAtString = obj["created_at"] as? String {
            createdAt = ISO8601DateFormatter().date(from: createdAtString) ?? Date()
        }

        return WorkflowRunInfo(
            id: (obj["id"] as? NSNumber)?.int64Value ?? 0,
            name: (obj["name"] as? String) ?? (obj["display_title"] as? String) ?? "workflow",
            status: status,
            conclusion: conclusion,
            headBranch: obj["head_branch"] as? String ?? "",
            event: obj["event"] as? String ?? "",
            htmlUrl: obj["html_url"] as? String ?? "",
            createdAt: createdAt
        )
    }

    private static func send(
        method: String, path: String, token: String, jsonBody: [String: Any]? = nil
    ) async throws -> (Data, HTTPURLResponse) {
        let url: URL
        if path.hasPrefix("http") {
            url = URL(string: path)!
        } else {
            url = URL(string: "\(apiBase)/\(path)")!
        }

        var request = URLRequest(url: url)
        request.httpMethod = method
        request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
        request.setValue("application/vnd.github+json", forHTTPHeaderField: "Accept")
        request.setValue("2022-11-28", forHTTPHeaderField: "X-GitHub-Api-Version")

        if let jsonBody {
            request.httpBody = try JSONSerialization.data(withJSONObject: jsonBody)
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        }

        let (data, response) = try await URLSession.shared.data(for: request)
        guard let httpResponse = response as? HTTPURLResponse else {
            throw GitHubApiError(statusCode: -1, message: "無效的伺服器回應。")
        }
        return (data, httpResponse)
    }

    private static func isSuccess(_ response: HTTPURLResponse) -> Bool {
        (200...299).contains(response.statusCode)
    }

    private static func ensureSuccess(_ response: HTTPURLResponse, data: Data) throws {
        if isSuccess(response) { return }
        throw GitHubApiError(statusCode: response.statusCode, message: readError(data: data, response: response))
    }

    private static func readError(data: Data, response: HTTPURLResponse) -> String {
        if let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
           let message = json["message"] as? String, !message.trimmingCharacters(in: .whitespaces).isEmpty {
            return message
        }
        return "GitHub API 回應 \(response.statusCode)"
    }

    private static func decodeBase64(_ base64: String) -> String {
        let cleaned = base64.replacingOccurrences(of: "\n", with: "").replacingOccurrences(of: "\r", with: "")
        guard let data = Data(base64Encoded: cleaned) else { return "" }
        return String(data: data, encoding: .utf8) ?? ""
    }

    private static func encodeBase64(_ text: String) -> String {
        Data(text.utf8).base64EncodedString()
    }

    private static func encodePath(_ path: String) -> String {
        path.split(separator: "/").map { encodeQueryValue(String($0)) }.joined(separator: "/")
    }

    private static func encodeQueryValue(_ value: String) -> String {
        value.addingPercentEncoding(withAllowedCharacters: .alphanumerics) ?? value
    }
}
